export type ParsedApproveOverrideInstruction<
  TProgram extends string = typeof BACKSTOP_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    caller: TAccountMetas[0];
    config: TAccountMetas[1];
    market: TAccountMetas[2];
    liquidationRecord: TAccountMetas[3];
    claim: TAccountMetas[4];
    overrideRequest: TAccountMetas[5];
    payoutBacker: TAccountMetas[6];
  };
  data: ApproveOverrideInstructionData;
};

export function parseApproveOverrideInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedApproveOverrideInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 7) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 7,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      caller: getNextAccount(),
      config: getNextAccount(),
      market: getNextAccount(),
      liquidationRecord: getNextAccount(),
      claim: getNextAccount(),
      overrideRequest: getNextAccount(),
      payoutBacker: getNextAccount(),
    },
    data: getApproveOverrideInstructionDataDecoder().decode(instruction.data),
  };
}
